// Exact released body with minimal release-layout declarations.
typedef float time_value_t;
extern "C" float sinf(float);

class PanelGeom {
    char data[116];
public:
    PanelGeom *children;
    PanelGeom *next;
    PanelGeom *parent;
    virtual ~PanelGeom();
    virtual int Kind() const = 0;
    virtual bool Load(unsigned char *, int &);
    virtual void Reload();
    virtual PanelGeom *FindObject(const void &);
    virtual void *GetQuad();
    virtual void Init(void **, bool = false);
    virtual void Init(void **, const void &, bool = false);
    virtual void Update(time_value_t);
    virtual void Slide(float);
};

class stringx { char data[8]; };

class PanelFile {
    enum { PF_SLIDE_NONE, PF_SLIDE_IN, PF_SLIDE_OUT, PF_SLIDE_IN_DONE, PF_SLIDE_OUT_DONE };
    int slide_state;
    float slide_offset;
    float slide_timer;
    float slide_max_time;
    stringx filename;
public:
    PanelGeom *obs;
    stringx path;
    PanelFile *next;
    void *pquads;
    virtual ~PanelFile();
    virtual PanelGeom *FindObject(const stringx &);
    virtual PanelGeom *FindObject(const char *);
    virtual void *FindQuad(const stringx &);
    virtual void SetFilename(stringx);
    bool IsSliding(void) const { return slide_state == PF_SLIDE_IN || slide_state == PF_SLIDE_OUT; }
    void Update(time_value_t) __asm__("Update__9PanelFilef");
};

void PanelFile::Update(time_value_t time_inc)
{
    if (IsSliding())
    {
        slide_timer += time_inc;
        if (slide_timer > slide_max_time)
        {
            slide_timer = 0;
            if (slide_state == PF_SLIDE_IN)
                slide_state = PF_SLIDE_IN_DONE;
            else
                slide_state = PF_SLIDE_OUT_DONE;
        }
        else
        {
            slide_offset = 320*(1+sinf(1.57f*(2*slide_timer/slide_max_time - 1)));
            if (slide_state == PF_SLIDE_IN)
                slide_offset = 640-slide_offset;
        }
    }

    PanelGeom* tmp = obs;
    while (tmp)
    {
        tmp->Update(time_inc);
        if (IsSliding())
            tmp->Slide(slide_offset);
        tmp = tmp->next;
    }
}
